import asyncioimport discordfrom discord.ext import commandsfrom utils import EmbedGeneratorUtilclass OnVoiceStateUpdateEvent(commands.Cog):    def __init__(self, bot: commands.Bot, ctx: commands.Context):        self.bot = bot        self.ctx = ctx    @commands.Cog.listener()    async def on_voice_state_update(self, member, before, after):        id = int(member.guild.id)        if member.id is not self.bot.user.id and before.channel is not None and after.channel is not before.channel:            remainingChannelMembers = before.channel.members            if len(remainingChannelMembers) == 1 and remainingChannelMembers[0].id is self.bot.user.id and self.bot.vc[id].is_connected():                self.bot.is_playing[id] = self.bot.is_paused[id] = False                self.bot.musicQueue[id] = []                self.bot.queueIndex[id] = 0                await asyncio.sleep(1.5)                print('test')                if self.bot.vc[id] is not None:                    await self.bot.vc[id].disconnect()async def setup(bot: commands.Bot):    await bot.add_cog(OnVoiceStateUpdateEvent(bot=bot, ctx=None))